import{_ as t,o as n,c as s,a2 as a}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"Cancel, Drain & Recovery","description":"","frontmatter":{},"headers":[],"relativePath":"guide/recovery.md","filePath":"guide/recovery.md","lastUpdated":1793010361000}'),o={name:"guide/recovery.md"};function r(c,e,l,d,i,p){return n(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="cancel-drain-recovery" tabindex="-1">Cancel, Drain &amp; Recovery <a class="header-anchor" href="#cancel-drain-recovery" aria-label="Permalink to &quot;Cancel, Drain &amp; Recovery&quot;">​</a></h1><h2 id="starting-and-stopping" tabindex="-1">Starting and stopping <a class="header-anchor" href="#starting-and-stopping" aria-label="Permalink to &quot;Starting and stopping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>What it does</th></tr></thead><tbody><tr><td><code>start()</code></td><td>Recovers abandoned runs, starts polling and starts queued runs</td></tr><tr><td><code>stop()</code></td><td>Stops the poll only. Runs in progress continue, and <code>dispatch()</code> still works</td></tr><tr><td><code>drain({ timeoutMs })</code></td><td>Graceful shutdown, see below</td></tr><tr><td><code>idle()</code></td><td>Resolves when nothing runs in this process and nothing more can start</td></tr><tr><td><code>isDraining</code></td><td><code>true</code> from <code>drain()</code> until the next <code>start()</code></td></tr></tbody></table><h2 id="cancel" tabindex="-1">Cancel <a class="header-anchor" href="#cancel" aria-label="Permalink to &quot;Cancel&quot;">​</a></h2><p><code>engine.cancel(runId)</code> depends on where the run is:</p><table tabindex="0"><thead><tr><th>Run</th><th>Result</th></tr></thead><tbody><tr><td>Executing in this engine</td><td>Aborted; settles <code>cancelled</code> and <code>cancel()</code> resolves once it settled</td></tr><tr><td><code>queued</code> or <code>waiting</code></td><td>Marked <code>cancelled</code> directly</td></tr><tr><td><code>running</code> on another replica, or <code>interrupted</code></td><td>Gets <code>cancelRequested: true</code>. The owner aborts it on its next poll (within <code>claimTtlMs / 3</code>); an interrupted run is settled <code>cancelled</code> on recovery, without a model call</td></tr><tr><td>Settled</td><td>Throws <code>InvalidRunStateError</code></td></tr><tr><td>Unknown</td><td>Throws <code>RunNotFoundError</code></td></tr></tbody></table><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.cancel(runId);</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> run = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.getRun(runId);</span></span>
<span class="line"><span style="color:#958A8B;">// RunStatus.CANCELLED, or still RunStatus.RUNNING with cancelRequested when another replica executes it</span></span>
<span class="line"><span style="color:#E6DFDE;">console.log(run?.status, run?.cancelRequested);</span></span></code></pre></div><p>If the local execution loses its lease while being cancelled, <code>cancel()</code> throws <code>InvalidRunStateError</code>: the run was not cancelled and may now execute on another replica. A cancel that races a pause cancels the run the pause left waiting, without sending the approval message.</p><h2 id="drain" tabindex="-1">Drain <a class="header-anchor" href="#drain" aria-label="Permalink to &quot;Drain&quot;">​</a></h2><p><code>drain({ timeoutMs })</code> is the shutdown path for a process that receives <code>SIGTERM</code>:</p><ol><li>It stops polling and starting runs. <code>dispatch()</code> still stores runs as <code>queued</code>, for another replica.</li><li>It waits up to <code>timeoutMs</code> (default 30 s) for in-flight runs to settle.</li><li>It aborts the rest and marks them <code>interrupted</code>, with their claim released. The writes of a step that already completed land first.</li></ol><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store,</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents,</span></span>
<span class="line"><span style="color:#E6DFDE;">    onError: (error, run) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> console.error(</span><span style="color:#E7C58C;">&#39;[agents]&#39;</span><span style="color:#E6DFDE;">, run?.id, error),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.start();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6DFDE;">process.once(</span><span style="color:#E7C58C;">&#39;SIGTERM&#39;</span><span style="color:#E6DFDE;">, () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#958A8B;">    // wait up to 25 s for in-flight runs, then mark the rest interrupted</span></span>
<span class="line"><span style="color:#E6DFDE;">    engine.drain({ timeoutMs: </span><span style="color:#E7C58C;">25_000</span><span style="color:#E6DFDE;"> })</span></span>
<span class="line"><span style="color:#E6DFDE;">        .then(() </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> process.exit(</span><span style="color:#E7C58C;">0</span><span style="color:#E6DFDE;">))</span></span>
<span class="line"><span style="color:#E6DFDE;">        .catch(() </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> process.exit(</span><span style="color:#E7C58C;">1</span><span style="color:#E6DFDE;">));</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>Only the drain deadline keeps the event loop alive; the engine&#39;s other timers never do. Pick a <code>timeoutMs</code> below your platform&#39;s grace period (Kubernetes&#39; <code>terminationGracePeriodSeconds</code>).</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery&quot;">​</a></h2><p><code>recover()</code> runs on <code>start()</code> and on every poll. It looks at every <code>running</code> or <code>interrupted</code> run:</p><ul><li>A run executing in this engine is left alone (unless another replica requested its cancel).</li><li>A run with a live claim of another owner is left alone.</li><li>Any other run (claim expired or released) is claimed atomically and requeued.</li></ul><p>The next execution continues from the latest checkpoint. A step whose checkpoint never landed runs again; <a href="/guide/effect-tools">effect tools</a> keep its side effects from repeating. <code>recover()</code> resolves the number of runs it requeued.</p><table tabindex="0"><thead><tr><th>Cause</th><th>Status left behind</th><th>Picked up</th></tr></thead><tbody><tr><td><code>drain()</code></td><td><code>interrupted</code>, claim released</td><td>on the next <code>recover()</code> of any engine</td></tr><tr><td>Crash or kill</td><td><code>running</code>, claim expires</td><td>after the lease expires, on the next <code>recover()</code></td></tr><tr><td>Lost network to the store</td><td><code>running</code> until the lease expires</td><td>as for a crash; the old owner stops writing once it notices</td></tr></tbody></table><p><code>MemoryStore</code> loses everything with the process, so recovery across restarts needs a durable store.</p>`,19)])])}const y=t(o,[["render",r]]);export{u as __pageData,y as default};
